                if($inst===''||$qual==='') throw new RuntimeException('Institution and qualification are required.');
                $data=[$inst,$qual,trim((string)($_POST['level']??'')),trim((string)($_POST['field_of_study']??'')),($_POST['year_started']??'')!==''?(int)$_POST['year_started']:null,($_POST['year_completed']??'')!==''?(int)$_POST['year_completed']:null,trim((string)($_POST['grade_obtained']??'')),trim((string)($_POST['status']??'Completed')),(int)!empty($_POST['is_highest_qualification'])];
                if($id){$st=$pdo->prepare('UPDATE staff_education SET institution=?,qualification=?,level=?,field_of_study=?,year_started=?,year_completed=?,grade_obtained=?,status=?,is_highest_qualification=? WHERE id=? AND svcNo=?');$st->execute([...$data,$id,$svc]);$message='Education record updated successfully.';}else{$st=$pdo->prepare('INSERT INTO staff_education (svcNo,institution,qualification,level,field_of_study,year_started,year_completed,grade_obtained,status,is_highest_qualification) VALUES (?,?,?,?,?,?,?,?,?,?)');$st->execute([$svc,...$data]);$message='Education record added successfully.';}
            } elseif($action==='course_record_save') {
