                $id=(int)($_POST['id']??0); $inst=trim((string)($_POST['instId']??'')); $cse=trim((string)($_POST['cseId']??''));
                if($inst==='' || $cse==='') throw new RuntimeException('Institution and course are required.');
                $q=$pdo->prepare('SELECT 1 FROM institution WHERE instId=? LIMIT 1'); $q->execute([$inst]); if(!$q->fetchColumn()) throw new RuntimeException('Selected institution does not exist.');
                $q=$pdo->prepare('SELECT 1 FROM course WHERE cseId=? LIMIT 1'); $q->execute([$cse]); if(!$q->fetchColumn()) throw new RuntimeException('Selected course does not exist.');
                $data=[$inst,$cse,trim((string)($_POST['qualification']??'')),($_POST['cseStart']??'')?:null,($_POST['cseEnd']??'')?:null,trim((string)($_POST['grade']??'')),trim((string)($_POST['result']??'')),(int)!empty($_POST['isHighest']),trim((string)($_POST['authID']??''))];
                if($id){$q=$pdo->prepare('UPDATE staff_course SET instId=?,cseId=?,qualification=?,cseStart=?,cseEnd=?,grade=?,result=?,isHighest=?,authID=? WHERE id=? AND svcNo=?');$q->execute([...$data,$id,$svc]);$message='Course record updated successfully.';}else{$q=$pdo->prepare('INSERT INTO staff_course (svcNo,instId,cseId,qualification,cseStart,cseEnd,grade,result,isHighest,authID) VALUES (?,?,?,?,?,?,?,?,?,?)');$q->execute([$svc,...$data]);$message='Course record added successfully.';}
            } elseif($action==='course_record_delete') {
                $svc=trim((string)($_POST['svcNo']??'')); if(!armisScopedStaffExists($pdo,$svc)) throw new RuntimeException('Personnel is outside your branch scope.'); $q=$pdo->prepare('DELETE FROM staff_course WHERE id=? AND svcNo=?'); $q->execute([(int)$_POST['id'],$svc]); $message='Course record removed successfully.';
            } else {
