                $data=[$course,trim((string)($_POST['course_type']??'')),trim((string)($_POST['institution']??'')),($_POST['startDate']??'')?:null,($_POST['endDate']??'')?:null,($_POST['duration_days']??'')!==''?(int)$_POST['duration_days']:null,trim((string)($_POST['certificateNumber']??'')),trim((string)($_POST['grade_obtained']??'')),trim((string)($_POST['location']??'')),($_POST['cost']??'')!==''?(float)$_POST['cost']:null,trim((string)($_POST['sponsored_by']??'')),trim((string)($_POST['certification_status']??''))];
                if($id){$st=$pdo->prepare('UPDATE staff_skills SET course_name=?,course_type=?,institution=?,startDate=?,endDate=?,duration_days=?,certificateNumber=?,grade_obtained=?,location=?,cost=?,sponsored_by=?,certification_status=? WHERE id=? AND svcNo=?');$st->execute([...$data,$id,$svc]);$message='Training/skill record updated successfully.';}else{$st=$pdo->prepare('INSERT INTO staff_skills (svcNo,course_name,course_type,institution,startDate,endDate,duration_days,certificateNumber,grade_obtained,location,cost,sponsored_by,certification_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$svc,...$data]);$message='Training/skill record added successfully.';}
            }
        } elseif($action==='education_delete'||$action==='skills_delete'){
            $svc=trim((string)($_POST['svcNo']??''));if(!armisScopedStaffExists($pdo,$svc))throw new RuntimeException('Personnel is outside your branch scope.');$table=$action==='education_delete'?'staff_education':'staff_skills';$st=$pdo->prepare("DELETE FROM {$table} WHERE id=? AND svcNo=?");$st->execute([(int)$_POST['id'],$svc]);$message='Record removed successfully.';
        } elseif($action==='master_course_save'){
            $id=trim((string)($_POST['cseId']??''));if($id==='')throw new RuntimeException('Course ID is required.');$st=$pdo->prepare('INSERT INTO course (cseId,cseType,cseLevel,createdBy) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE cseType=VALUES(cseType),cseLevel=VALUES(cseLevel)');$st->execute([$id,$_POST['cseType']?:null,$_POST['cseLevel']?:null,(string)($_SESSION['user_id']??'')]);$message='Education course master record saved.';
