        }
    }catch(Throwable $e){$error=$e->getMessage();}
}
[$scopeSql,$scopeParams]=armisScopedStaffWhere('s');$st=$pdo->prepare("SELECT s.svcNo,s.fName,s.mName,s.lName,s.rankId,s.unitId FROM staff s WHERE {$scopeSql} AND s.svcStatus='Active' ORDER BY s.lName,s.fName,s.svcNo");$st->execute($scopeParams);$personnel=$st->fetchAll(PDO::FETCH_ASSOC);
